package com.adview.adapters;

    public void displayCustom() {
        Activity activity;
        AdViewLayout adViewLayout = this.adViewLayoutReference.get();
        if (adViewLayout != null && (activity = adViewLayout.activityReference.get()) != null) {
            switch (adViewLayout.custom.type) {
                case 1:
                    Log.d(AdViewUtil.ADVIEW, "Serving custom type: banner");
                    RelativeLayout bannerView = new RelativeLayout(activity);
                    if (adViewLayout.custom.image == null) {
                        adViewLayout.rotateThreadedNow();
                        return;
                    }
                    ImageView bannerImageView = new ImageView(activity);
                    bannerImageView.setImageDrawable(adViewLayout.custom.image);
                    RelativeLayout.LayoutParams bannerViewParams = new RelativeLayout.LayoutParams(-2, -2);
                    bannerViewParams.addRule(13);
                    bannerView.addView(bannerImageView, bannerViewParams);
                    adViewLayout.pushSubView(bannerView);
                    break;
                case 2:
                    Log.d(AdViewUtil.ADVIEW, "Serving custom type: icon");
                    RelativeLayout iconView = new RelativeLayout(activity);
                    if (adViewLayout.custom.image == null) {
                        adViewLayout.rotateThreadedNow();
                        return;
                    }
                    iconView.setLayoutParams(new FrameLayout.LayoutParams(320, 50));
                    ImageView blendView = new ImageView(activity);
                    int backgroundColor = Color.rgb(adViewLayout.extra.bgRed, adViewLayout.extra.bgGreen, adViewLayout.extra.bgBlue);
                    GradientDrawable blend = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{-1, backgroundColor, backgroundColor, backgroundColor});
                    blendView.setBackgroundDrawable(blend);
                    RelativeLayout.LayoutParams blendViewParams = new RelativeLayout.LayoutParams(-1, -1);
                    iconView.addView(blendView, blendViewParams);
                    ImageView iconImageView = new ImageView(activity);
                    iconImageView.setImageDrawable(adViewLayout.custom.image);
                    iconImageView.setId(10);
                    iconImageView.setPadding(4, 0, 6, 0);
                    iconImageView.setScaleType(ImageView.ScaleType.CENTER);
                    RelativeLayout.LayoutParams iconViewParams = new RelativeLayout.LayoutParams(-2, -1);
                    iconView.addView(iconImageView, iconViewParams);
                    ImageView frameImageView = new ImageView(activity);
                    InputStream drawableStream = getClass().getResourceAsStream("/com/adwhirl/assets/ad_frame.gif");
                    Drawable adFrameDrawable = new BitmapDrawable(drawableStream);
                    frameImageView.setImageDrawable(adFrameDrawable);
                    frameImageView.setPadding(4, 0, 6, 0);
                    frameImageView.setScaleType(ImageView.ScaleType.CENTER);
                    RelativeLayout.LayoutParams frameViewParams = new RelativeLayout.LayoutParams(-2, -1);
                    iconView.addView(frameImageView, frameViewParams);
                    TextView iconTextView = new TextView(activity);
                    iconTextView.setText(adViewLayout.custom.description);
                    iconTextView.setTypeface(Typeface.DEFAULT_BOLD, 1);
                    iconTextView.setTextColor(Color.rgb(adViewLayout.extra.fgRed, adViewLayout.extra.fgGreen, adViewLayout.extra.fgBlue));
                    RelativeLayout.LayoutParams textViewParams = new RelativeLayout.LayoutParams(-1, -1);
                    textViewParams.addRule(1, iconImageView.getId());
                    textViewParams.addRule(10);
                    textViewParams.addRule(12);
                    textViewParams.addRule(15);
                    textViewParams.addRule(13);
                    iconTextView.setGravity(16);
                    iconView.addView(iconTextView, textViewParams);
                    adViewLayout.pushSubView(iconView);
                    break;
                default:
                    Log.w(AdViewUtil.ADVIEW, "Unknown custom type!");
                    adViewLayout.rotateThreadedNow();
                    return;
            }
            adViewLayout.adViewManager.resetRollover();
            adViewLayout.rotateThreadedDelayed();
        }
    }

