    void MathResult() {
        if (checkEditText() != 1) {
            this.strResultContent = "请把信息填写完整，不能为0或者为空";
            Intent intent = new Intent(this, (Class<?>) DialogActivity.class);
            Bundle newBundle = new Bundle();
            newBundle.putString("strMsg", this.strResultContent);
            intent.putExtras(newBundle);
            startActivity(intent);
            return;
        }
        this.strResultContent = "";
        switch (this.iFunType) {
            case R.id.ImageView_Tile /* 2130968685 */:
                if (ETF(this.etML) <= ETF(this.etFH) && ETF(this.etMW) <= ETF(this.etFW) && ETF(this.etMW) <= ETF(this.etFL)) {
                    if (ETF(this.etCL) > ETF(this.etFH) || ETF(this.etCW) > ETF(this.etFW)) {
                        this.strResultContent = String.valueOf(getString(R.string.C_L_name)) + "或者" + getString(R.string.C_W_name) + "太大";
                        break;
                    } else {
                        Integer iWallBrick = Integer.valueOf(this.gCalculator.wallBrick(ETF(this.etFL), ETF(this.etFW), ETF(this.etFH), ETF(this.etML), ETF(this.etMW), ETI(this.etMN), ETF(this.etCL), ETF(this.etCW), ETI(this.etCN), ETF(this.etZL) * 0.001f, ETF(this.etZW) * 0.001f, 1.05f));
                        if (iWallBrick.intValue() <= 0) {
                            this.strResultContent = String.valueOf(getString(R.string.M_N_name)) + "或者" + getString(R.string.C_N_name) + "太多";
                            break;
                        } else {
                            this.strResultContent = "您所需要的墙砖数量是\n" + Integer.toString(iWallBrick.intValue()) + "块";
                            break;
                        }
                    }
                } else {
                    this.strResultContent = String.valueOf(getString(R.string.M_L_name)) + "或者" + getString(R.string.M_W_name) + "太大";
                    break;
                }
                break;
            case R.id.ImageView_Floortile /* 2130968687 */:
                this.strResultContent = "您所需要的地砖数量是\n" + Integer.toString(this.gCalculator.floorTiles(ETF(this.etFL), ETF(this.etFW), ETF(this.etDL) * 0.001f, ETF(this.etDW) * 0.001f, 1.05f)) + "块";
                break;
            case R.id.ImageView_Floor /* 2130968691 */:
                this.strResultContent = "您所需要的地板数量是\n" + Integer.toString(this.gCalculator.floor(ETF(this.etFL), ETF(this.etFW), ETF(this.etBL) * 0.001f, ETF(this.etBW) * 0.001f, 1.05f)) + "块";
                break;
            case R.id.ImageView_Wallpaper /* 2130968694 */:
                this.strResultContent = "您所需要的墙纸数量是\n" + Integer.toString(this.gCalculator.wallpaper(ETF(this.etFL), ETF(this.etFW), ETF(this.etFH), ETF(this.etJP), 1.1f)) + "卷";
                break;
            case R.id.ImageView_Print /* 2130968698 */:
                if (ETF(this.etML) <= ETF(this.etFH) && ETF(this.etMW) <= ETF(this.etFW) && ETF(this.etMW) <= ETF(this.etFL)) {
                    if (ETF(this.etCL) > ETF(this.etFH) || ETF(this.etCW) > ETF(this.etFW)) {
                        this.strResultContent = String.valueOf(getString(R.string.C_L_name)) + "或者" + getString(R.string.C_W_name) + "太大";
                        break;
                    } else {
                        Float fPaint = Float.valueOf(this.gCalculator.Paint(ETF(this.etFL), ETF(this.etFW), ETF(this.etFH), ETF(this.etML), ETF(this.etMW), ETI(this.etMN), ETF(this.etCL), ETF(this.etCW), ETI(this.etCN), ETF(this.etTL)));
                        if (fPaint.floatValue() <= 0.0f) {
                            this.strResultContent = String.valueOf(getString(R.string.M_N_name)) + "或者" + getString(R.string.C_N_name) + "太多";
                            break;
                        } else {
                            this.strResultContent = "您所需要的涂料是\n" + Float.toString(fPaint.floatValue()) + "升";
                            break;
                        }
                    }
                } else {
                    this.strResultContent = String.valueOf(getString(R.string.M_L_name)) + "或者" + getString(R.string.M_W_name) + "太大";
                    break;
                }
                break;
            case R.id.ImageView_Curtain /* 2130968701 */:
                this.strResultContent = "您所需要的布料是\n" + Integer.toString(this.gCalculator.CurtainLength(ETF(this.etCL), ETF(this.etCW), ETF(this.etPL))) + "米";
                break;
        }
        Intent intent2 = new Intent(this, (Class<?>) DialogActivity.class);
        Bundle newBundle2 = new Bundle();
        newBundle2.putString("strMsg", this.strResultContent);
        intent2.putExtras(newBundle2);
        startActivity(intent2);
    }

